const items = $input.all();
return items.map(item => {
  const data = item.json;
  const spend = parseFloat(data.spend || '0');
  const impressions = parseInt(data.impressions || '0', 10);
  const clicks = parseInt(data.clicks || '0', 10);
  const conversions = parseInt(data.conversions || data.conversion || '0', 10);
  const videoPlays = parseInt(data.video_play_actions || '0', 10);
  const views3s = parseInt(data.video_watched_3s || data.video_play_actions || '0', 10);
  const views50 = parseInt(data.video_views_p50 || data.video_p50_watched_actions || '0', 10);

  // Direct Response Formula Math
  const thumbstopRate = impressions > 0 ? Number(((views3s / impressions) * 100).toFixed(2)) : 0;
  const holdRate = views3s > 0 ? Number(((views50 / views3s) * 100).toFixed(2)) : 0;
  const cpa = conversions > 0 ? Number((spend / conversions).toFixed(2)) : 0;
  const roas = spend > 0 ? Number(((conversions * 45.0) / spend).toFixed(2)) : 0;

  return {
    json: {
      variant_id: data.variant_id || '00000000-0000-0000-0000-000000000001',
      platform: data.platform || 'meta',
      date: new Date().toISOString().split('T')[0],
      spend,
      impressions,
      clicks,
      conversions,
      cpa,
      roas,
      hook_rate: thumbstopRate,
      hold_rate: holdRate,
      attributes: {
        angle: data.angle,
        framework: data.framework,
        target_persona: data.target_persona
      }
    }
  };
});
